// Generated by sema from execution_model and execution_contract.
#[derive(Clone, Debug, PartialEq)]
pub enum Value {
    Int(i32),
    Float(f32),
    Bool(bool),
    Char(u8),
    Pointer(Option<usize>),
    Struct(Vec<Value>),
    Array(Vec<Value>),
    Reference(PlaceView),
    Void,
    Uninitialized,
}

#[derive(Clone, Debug, PartialEq)]
pub enum Control {
    Continue,
    Return(Value),
}

#[derive(Clone, Debug, PartialEq)]
pub struct RuntimeError {
    pub message: &'static str,
    pub source: InputSpan,
}

#[derive(Clone, Debug, PartialEq)]
pub struct PlaceView {
    pub root: SymbolId,
    pub fields: Vec<usize>,
}

#[derive(Clone, Debug, PartialEq)]
pub struct BoundPlace {
    pub place: PlaceId,
    pub view: PlaceView,
    pub depth: usize,
}

#[derive(Clone, Debug, PartialEq)]
pub struct FunctionView {
    pub body: Option<OpId>,
    pub parameters: Vec<Type>,
    pub symbols: Option<Vec<SymbolId>>,
    pub result: Type,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Runtime {
    pub store: agsem_runtime::Store<SymbolId, Value>,
    pub steps_remaining: usize,
    pub globals_finished: bool,
    pub bound_places: Vec<BoundPlace>,
}

pub struct Interpreter<'a> {
    context: &'a Context,
    runtime: Runtime,
}

impl<'a> Interpreter<'a> {
    fn initialize_globals(&mut self) -> Result<(), RuntimeError> {
        let operations = self.module_operations()?;
        for operation in operations {
            self.initialize_global(operation)?;
        }
        return Ok(());
    }

    fn declare(&mut self, symbol: SymbolId, _source: InputSpan) -> Result<(), RuntimeError> {
        let ty = self.variable_type(symbol)?;
        let value = self.value_for_type(ty, self.runtime.store.is_global())?;
        self.runtime.store.insert_current(symbol, value);
        return Ok(());
    }

    fn value_for_type(&self, ty: Type, zero: bool) -> Result<Value, RuntimeError> {
        match ty {
            Type::Struct(structure) => {
                return self.structure_value(structure, zero);
            }
            Type::Array(element, length) => {
                return self.array_value(agsem_runtime::unbox(element), length, zero);
            }
            _ => {
                return self.scalar_value(ty, zero);
            }
        }
    }

    fn structure_value(&self, structure: StructId, zero: bool) -> Result<Value, RuntimeError> {
        let types = self.field_types(structure)?;
        let mut values = agsem_runtime::list();
        for ty in types {
            let value = self.value_for_type(ty, zero)?;
            values.push(value);
        }
        return Ok(Value::Struct(values));
    }

    fn array_value(&self, element: Type, length: usize, zero: bool) -> Result<Value, RuntimeError> {
        let mut values = agsem_runtime::list();
        for _index in agsem_runtime::indices(length) {
            let value = self.value_for_type(element.clone(), zero)?;
            values.push(value);
        }
        return Ok(Value::Array(values));
    }

    fn scalar_value(&self, ty: Type, zero: bool) -> Result<Value, RuntimeError> {
        if zero == false {
            return Ok(Value::Uninitialized);
        }
        match ty {
            Type::Int => {
                return Ok(Value::Int(0));
            }
            Type::Float => {
                return Ok(Value::Float(0.0));
            }
            Type::Bool => {
                return Ok(Value::Bool(false));
            }
            Type::Char => {
                return Ok(Value::Char(0));
            }
            Type::CharPointer => {
                return Ok(Value::Pointer(None));
            }
            Type::NullPointer => {
                return Ok(Value::Pointer(None));
            }
            Type::Void => {
                return Ok(Value::Void);
            }
            _ => {
                return Ok(Value::Uninitialized);
            }
        }
    }

    fn structure_matches(&self, values: Vec<Value>, structure: StructId) -> Result<bool, RuntimeError> {
        let types = self.field_types(structure)?;
        return self.values_match(values, types);
    }

    fn values_match(&self, values: Vec<Value>, types: Vec<Type>) -> Result<bool, RuntimeError> {
        if values.len() != types.len() {
            return Ok(false);
        }
        for pair in agsem_runtime::zip(values, types) {
            let valid = self.value_matches_type(pair.first, pair.second)?;
            if valid == false {
                return Ok(false);
            }
        }
        return Ok(true);
    }

    fn array_matches(&self, values: Vec<Value>, element: Type, length: usize) -> Result<bool, RuntimeError> {
        if values.len() != length {
            return Ok(false);
        }
        for value in values {
            let valid = self.value_matches_type(value, element.clone())?;
            if valid == false {
                return Ok(false);
            }
        }
        return Ok(true);
    }

    fn initialized_value(&self, value: Value, source: InputSpan) -> Result<Value, RuntimeError> {
        match value {
            Value::Uninitialized => {
                return Err(RuntimeError { message: "variable used before initialization", source: source });
            }
            _ => {
                return Ok(value);
            }
        }
    }

    fn store(&mut self, place: PlaceId, value: Value, source: InputSpan) -> Result<(), RuntimeError> {
        let key = self.place_view(place)?;
        match self.runtime.store.write_path(key.root, key.fields, value) {
            Ok(_done) => {
                return Ok(());
            }
            Err(fault) => {
                match fault {
                    AccessError::MissingRoot => {
                        return Err(RuntimeError { message: "missing runtime variable", source: source });
                    }
                    AccessError::InvalidPath => {
                        return Err(RuntimeError { message: "invalid runtime field", source: source });
                    }
                }
            }
        }
    }

    fn write_symbol(&mut self, symbol: SymbolId, value: Value, source: InputSpan) -> Result<(), RuntimeError> {
        let place = self.variable_place(symbol)?;
        return self.store(place, value, source);
    }

    fn write(&mut self, place: PlaceId, value: Value, source: InputSpan) -> Result<(), RuntimeError> {
        return self.store(place, value, source);
    }

    fn call(&mut self, callee: FunctionId, arguments: Vec<Value>, source: InputSpan) -> Result<Value, RuntimeError> {
        let signature = self.function_view(callee)?;
        let body = self.function_body(signature.body, source)?;
        if arguments.len() != signature.parameters.len() {
            return Err(RuntimeError { message: "wrong number of arguments", source: source });
        }
        let valid = self.values_match(arguments.clone(), signature.parameters)?;
        if valid == false {
            return Err(RuntimeError { message: "incompatible argument type", source: source });
        }
        if self.runtime.store.depth() >= 256 {
            return Err(RuntimeError { message: "call depth exceeded", source: source });
        }
        let symbols = self.function_symbols(signature.symbols, source)?;
        self.runtime.store.push_bindings(symbols, arguments);
        let outcome = self.execute(body);
        self.runtime.store.pop();
        return self.finish_call(outcome, signature.result, source);
    }

    fn function_body(&self, body: Option<OpId>, source: InputSpan) -> Result<OpId, RuntimeError> {
        match body {
            Some(operation) => {
                return Ok(operation);
            }
            None => {
                return Err(RuntimeError { message: "undefined function", source: source });
            }
        }
    }

    fn function_symbols(&self, symbols: Option<Vec<SymbolId>>, source: InputSpan) -> Result<Vec<SymbolId>, RuntimeError> {
        match symbols {
            Some(values) => {
                return Ok(values);
            }
            None => {
                return Err(RuntimeError { message: "missing function scope", source: source });
            }
        }
    }

    fn finish_call(&self, outcome: Result<Control, RuntimeError>, result: Type, source: InputSpan) -> Result<Value, RuntimeError> {
        match outcome {
            Ok(control) => {
                return self.finish_control(control, result, source);
            }
            Err(fault) => {
                return Err(RuntimeError { message: fault.message, source: fault.source });
            }
        }
    }

    fn finish_control(&self, control: Control, result: Type, source: InputSpan) -> Result<Value, RuntimeError> {
        match control {
            Control::Return(value) => {
                return Ok(value);
            }
            Control::Continue => {
                if result == Type::Void {
                    return Ok(Value::Void);
                } else {
                    return Err(RuntimeError { message: "missing return statement", source: source });
                }
            }
        }
    }

    fn evaluate_call(&mut self, callee: FunctionId, arguments: Vec<ExprId>, source: InputSpan) -> Result<Value, RuntimeError> {
        let mut values = agsem_runtime::list();
        for argument in arguments {
            let value = self.evaluate(argument)?;
            values.push(value);
        }
        return self.call(callee, values, source);
    }

    fn binary_checked(&self, operator: Operator, right: ExprId, lhs: Value, rhs: Value, checks: Vec<RuntimeCheck>, source: InputSpan) -> Result<Value, RuntimeError> {
        for check in checks {
            match check {
                RuntimeCheck::Nonzero(checked) => {
                    if checked == right {
                        if rhs == Value::Int(0) {
                            return Err(RuntimeError { message: "division by zero", source: source });
                        }
                    }
                }
            }
        }
        return self.binary(operator, lhs, rhs, source);
    }

    fn char_to_int(&self, value: u8) -> Result<i32, RuntimeError> {
        return Ok(agsem_runtime::char_to_int(value));
    }

    fn char_to_float(&self, value: u8) -> Result<f32, RuntimeError> {
        return Ok(agsem_runtime::char_to_float(value));
    }

    fn int_to_float(&self, value: i32) -> Result<f32, RuntimeError> {
        return Ok(agsem_runtime::int_to_float(value));
    }

    fn int_to_char(&self, value: i32) -> Result<u8, RuntimeError> {
        return Ok(agsem_runtime::int_to_char(value));
    }

    fn float_to_int(&self, value: f32) -> Result<i32, RuntimeError> {
        return Ok(agsem_runtime::float_to_int(value));
    }

    fn float_to_char(&self, value: f32) -> Result<u8, RuntimeError> {
        return Ok(agsem_runtime::float_to_char(value));
    }

    fn tick(&mut self, source: InputSpan) -> Result<(), RuntimeError> {
        if self.runtime.steps_remaining == 0 {
            return Err(RuntimeError { message: "execution limit exceeded", source: source });
        }
        self.runtime.steps_remaining = self.runtime.steps_remaining - 1;
        return Ok(());
    }

    fn checked_neg_i32(&self, number: i32, source: InputSpan) -> Result<i32, RuntimeError> {
        let result = agsem_runtime::checked_neg_i32(number);
        match result {
            Some(value) => {
                return Ok(value);
            }
            _ => {
                return Err(RuntimeError { message: "integer overflow", source: source });
            }
        }
    }

    fn checked_add_i32(&self, left: i32, right: i32, source: InputSpan) -> Result<i32, RuntimeError> {
        let result = agsem_runtime::checked_add_i32(left, right);
        match result {
            Some(value) => {
                return Ok(value);
            }
            _ => {
                return Err(RuntimeError { message: "integer overflow", source: source });
            }
        }
    }

    fn checked_sub_i32(&self, left: i32, right: i32, source: InputSpan) -> Result<i32, RuntimeError> {
        let result = agsem_runtime::checked_sub_i32(left, right);
        match result {
            Some(value) => {
                return Ok(value);
            }
            _ => {
                return Err(RuntimeError { message: "integer overflow", source: source });
            }
        }
    }

    fn checked_mul_i32(&self, left: i32, right: i32, source: InputSpan) -> Result<i32, RuntimeError> {
        let result = agsem_runtime::checked_mul_i32(left, right);
        match result {
            Some(value) => {
                return Ok(value);
            }
            _ => {
                return Err(RuntimeError { message: "integer overflow", source: source });
            }
        }
    }

    fn checked_div_i32(&self, left: i32, right: i32, source: InputSpan) -> Result<i32, RuntimeError> {
        let result = agsem_runtime::checked_div_i32(left, right);
        match result {
            Some(value) => {
                return Ok(value);
            }
            _ => {
                if right == 0 {
                    return Err(RuntimeError { message: "division by zero", source: source });
                } else {
                    return Err(RuntimeError { message: "integer overflow", source: source });
                }
            }
        }
    }

    fn execute(&mut self, operation: OpId) -> Result<Control, RuntimeError> {
        let node = self.operation_node(operation)?;
        self.tick(node.source)?;
        return self.execute_generated(node.kind, node.source);
    }

    fn evaluate(&mut self, expression: ExprId) -> Result<Value, RuntimeError> {
        let node = self.expression_node(expression)?;
        self.tick(node.source)?;
        return self.evaluate_generated(node.kind, node.checks, expression, node.source);
    }

    fn condition_truthy(&mut self, condition: ExprId, source: InputSpan) -> Result<bool, RuntimeError> {
        let value = self.evaluate(condition)?;
        return self.truthy(value, source);
    }

    fn truthy(&self, value: Value, source: InputSpan) -> Result<bool, RuntimeError> {
        match value {
            Value::Bool(flag) => {
                return Ok(flag);
            }
            Value::Int(number) => {
                return Ok(number != 0);
            }
            Value::Float(number) => {
                return Ok(number != 0.0);
            }
            Value::Char(number) => {
                return Ok(number != 0);
            }
            Value::Pointer(pointer) => {
                return Ok(pointer != None);
            }
            _ => {
                return Err(RuntimeError { message: "invalid condition value", source: source });
            }
        }
    }

    fn execute_optional(&mut self, operation: Option<OpId>) -> Result<Control, RuntimeError> {
        match operation {
            Some(child) => {
                return self.execute(child);
            }
            None => {
                return Ok(Control::Continue);
            }
        }
    }

    fn control_return(&self, value: Value) -> Result<Control, RuntimeError> {
        return Ok(Control::Return(value));
    }

    fn no_op(&self) -> Result<(), RuntimeError> {
        return Ok(());
    }

    fn return_value(&mut self, value: Option<ExprId>) -> Result<Control, RuntimeError> {
        match value {
            Some(expression) => {
                return Ok(Control::Return(self.evaluate(expression)?));
            }
            None => {
                return Ok(Control::Return(Value::Void));
            }
        }
    }

    fn invalid_operation(&self, source: InputSpan) -> Result<Control, RuntimeError> {
        return Err(RuntimeError { message: "invalid semantic IR", source: source });
    }

    fn invalid_value(&self, source: InputSpan) -> Result<Value, RuntimeError> {
        return Err(RuntimeError { message: "invalid semantic IR", source: source });
    }

    fn value_from_constant(&self, constant: Constant, expression: ExprId) -> Result<Value, RuntimeError> {
        match constant {
            Constant::Int(number) => {
                return Ok(Value::Int(number));
            }
            Constant::Float(number) => {
                return Ok(Value::Float(number));
            }
            Constant::Bool(flag) => {
                return Ok(Value::Bool(flag));
            }
            Constant::Char(character) => {
                return Ok(Value::Char(character));
            }
            Constant::String(_literal) => {
                return Ok(Value::Pointer(Some(self.literal_identity(expression)?)));
            }
            Constant::Null => {
                return Ok(Value::Pointer(None));
            }
        }
    }

    fn negate(&self, value: Value, source: InputSpan) -> Result<Value, RuntimeError> {
        match value {
            Value::Int(number) => {
                return Ok(Value::Int(self.checked_neg_i32(number, source)?));
            }
            Value::Float(number) => {
                return Ok(Value::Float(-number));
            }
            _ => {
                return Err(RuntimeError { message: "invalid unary operand", source: source });
            }
        }
    }

    fn binary(&self, operator: Operator, left: Value, right: Value, source: InputSpan) -> Result<Value, RuntimeError> {
        match left {
            Value::Int(a) => {
                match right {
                    Value::Int(b) => {
                        match operator {
                            Operator::Add => {
                                return Ok(Value::Int(self.checked_add_i32(a, b, source)?));
                            }
                            Operator::Subtract => {
                                return Ok(Value::Int(self.checked_sub_i32(a, b, source)?));
                            }
                            Operator::Multiply => {
                                return Ok(Value::Int(self.checked_mul_i32(a, b, source)?));
                            }
                            Operator::Divide => {
                                return Ok(Value::Int(self.checked_div_i32(a, b, source)?));
                            }
                            Operator::Less => {
                                return Ok(Value::Bool(a < b));
                            }
                            Operator::LessEqual => {
                                return Ok(Value::Bool(a <= b));
                            }
                            Operator::Greater => {
                                return Ok(Value::Bool(a > b));
                            }
                            Operator::GreaterEqual => {
                                return Ok(Value::Bool(a >= b));
                            }
                            Operator::Equal => {
                                return Ok(Value::Bool(a == b));
                            }
                            Operator::NotEqual => {
                                return Ok(Value::Bool(a != b));
                            }
                        }
                    }
                    _ => {
                        return Err(RuntimeError { message: "invalid binary operands", source: source });
                    }
                }
            }
            Value::Float(a) => {
                match right {
                    Value::Float(b) => {
                        match operator {
                            Operator::Add => {
                                return Ok(Value::Float(a + b));
                            }
                            Operator::Subtract => {
                                return Ok(Value::Float(a - b));
                            }
                            Operator::Multiply => {
                                return Ok(Value::Float(a * b));
                            }
                            Operator::Divide => {
                                return Ok(Value::Float(a / b));
                            }
                            Operator::Less => {
                                return Ok(Value::Bool(a < b));
                            }
                            Operator::LessEqual => {
                                return Ok(Value::Bool(a <= b));
                            }
                            Operator::Greater => {
                                return Ok(Value::Bool(a > b));
                            }
                            Operator::GreaterEqual => {
                                return Ok(Value::Bool(a >= b));
                            }
                            Operator::Equal => {
                                return Ok(Value::Bool(a == b));
                            }
                            Operator::NotEqual => {
                                return Ok(Value::Bool(a != b));
                            }
                        }
                    }
                    _ => {
                        return Err(RuntimeError { message: "invalid binary operands", source: source });
                    }
                }
            }
            Value::Bool(a) => {
                match right {
                    Value::Bool(b) => {
                        match operator {
                            Operator::Equal => {
                                return Ok(Value::Bool(a == b));
                            }
                            Operator::NotEqual => {
                                return Ok(Value::Bool(a != b));
                            }
                            _ => {
                                return Err(RuntimeError { message: "invalid boolean operation", source: source });
                            }
                        }
                    }
                    _ => {
                        return Err(RuntimeError { message: "invalid binary operands", source: source });
                    }
                }
            }
            Value::Pointer(a) => {
                match right {
                    Value::Pointer(b) => {
                        match operator {
                            Operator::Equal => {
                                return Ok(Value::Bool(a == b));
                            }
                            Operator::NotEqual => {
                                return Ok(Value::Bool(a != b));
                            }
                            _ => {
                                return Err(RuntimeError { message: "invalid pointer operation", source: source });
                            }
                        }
                    }
                    _ => {
                        return Err(RuntimeError { message: "invalid binary operands", source: source });
                    }
                }
            }
            _ => {
                return Err(RuntimeError { message: "invalid binary operands", source: source });
            }
        }
    }

    fn convert(&self, value: Value, target: Type, source: InputSpan) -> Result<Value, RuntimeError> {
        if target == Type::Bool {
            return Ok(Value::Bool(self.truthy(value, source)?));
        }
        match value {
            Value::Char(number) => {
                match target {
                    Type::Int => {
                        return Ok(Value::Int(self.char_to_int(number)?));
                    }
                    Type::Float => {
                        return Ok(Value::Float(self.char_to_float(number)?));
                    }
                    Type::Char => {
                        return Ok(Value::Char(number));
                    }
                    _ => {
                        return Err(RuntimeError { message: "invalid runtime conversion", source: source });
                    }
                }
            }
            Value::Int(number) => {
                match target {
                    Type::Float => {
                        return Ok(Value::Float(self.int_to_float(number)?));
                    }
                    Type::Char => {
                        return Ok(Value::Char(self.int_to_char(number)?));
                    }
                    Type::Int => {
                        return Ok(Value::Int(number));
                    }
                    _ => {
                        return Err(RuntimeError { message: "invalid runtime conversion", source: source });
                    }
                }
            }
            Value::Float(number) => {
                match target {
                    Type::Int => {
                        return Ok(Value::Int(self.float_to_int(number)?));
                    }
                    Type::Char => {
                        return Ok(Value::Char(self.float_to_char(number)?));
                    }
                    Type::Float => {
                        return Ok(Value::Float(number));
                    }
                    _ => {
                        return Err(RuntimeError { message: "invalid runtime conversion", source: source });
                    }
                }
            }
            Value::Pointer(pointer) => {
                match target {
                    Type::CharPointer => {
                        return Ok(Value::Pointer(pointer));
                    }
                    Type::NullPointer => {
                        return Ok(Value::Pointer(pointer));
                    }
                    _ => {
                        return Err(RuntimeError { message: "invalid runtime conversion", source: source });
                    }
                }
            }
            Value::Struct(fields) => {
                match target {
                    Type::Struct(_structure) => {
                        return Ok(Value::Struct(fields));
                    }
                    _ => {
                        return Err(RuntimeError { message: "invalid runtime conversion", source: source });
                    }
                }
            }
            Value::Array(items) => {
                match target {
                    Type::Array(_element, _length) => {
                        return Ok(Value::Array(items));
                    }
                    _ => {
                        return Err(RuntimeError { message: "invalid runtime conversion", source: source });
                    }
                }
            }
            Value::Void => {
                match target {
                    Type::Void => {
                        return Ok(Value::Void);
                    }
                    _ => {
                        return Err(RuntimeError { message: "invalid runtime conversion", source: source });
                    }
                }
            }
            _ => {
                return Err(RuntimeError { message: "invalid runtime conversion", source: source });
            }
        }
    }

    fn initialize_global(&mut self, operation: OpId) -> Result<(), RuntimeError> {
        let node = self.operation_node(operation)?;
        match node.kind {
            Operation::Declare(symbol) => {
                return self.declare(symbol, node.source);
            }
            Operation::Construct(symbol, constructor, arguments) => {
                return self.initialize_global_object(symbol, constructor, arguments, node.source);
            }
            _ => {
                return Err(RuntimeError { message: "invalid global declaration", source: node.source });
            }
        }
    }

    fn initialize_global_object(&mut self, symbol: SymbolId, constructor: Option<FunctionId>, arguments: Vec<ExprId>, source: InputSpan) -> Result<(), RuntimeError> {
        self.construct(symbol, constructor, arguments, source)?;
        return Ok(());
    }

    fn value_matches_type(&self, value: Value, ty: Type) -> Result<bool, RuntimeError> {
        match value {
            Value::Int(_number) => {
                return Ok(ty == Type::Int);
            }
            Value::Float(_number) => {
                return Ok(ty == Type::Float);
            }
            Value::Bool(_flag) => {
                return Ok(ty == Type::Bool);
            }
            Value::Char(_character) => {
                return Ok(ty == Type::Char);
            }
            Value::Void => {
                return Ok(ty == Type::Void);
            }
            Value::Pointer(_pointer) => {
                if ty == Type::CharPointer {
                    return Ok(true);
                } else {
                    return Ok(ty == Type::NullPointer);
                }
            }
            Value::Reference(place) => {
                return self.reference_matches_type(place, ty);
            }
            Value::Struct(values) => {
                match ty {
                    Type::Struct(structure) => {
                        return self.structure_matches(values, structure);
                    }
                    _ => {
                        return Ok(false);
                    }
                }
            }
            Value::Array(values) => {
                match ty {
                    Type::Array(element, length) => {
                        return self.array_matches(values, agsem_runtime::unbox(element), length);
                    }
                    _ => {
                        return Ok(false);
                    }
                }
            }
            _ => {
                return Ok(false);
            }
        }
    }

    fn load(&mut self, place: PlaceId, source: InputSpan) -> Result<Value, RuntimeError> {
        let key = self.place_view(place)?;
        match self.runtime.store.load_path(key.root, key.fields) {
            Ok(value) => {
                return self.initialized_value(value, source);
            }
            Err(fault) => {
                match fault {
                    AccessError::MissingRoot => {
                        return Err(RuntimeError { message: "missing runtime variable", source: source });
                    }
                    AccessError::InvalidPath => {
                        return Err(RuntimeError { message: "invalid runtime field", source: source });
                    }
                }
            }
        }
    }

    fn return_with_cleanup(&mut self, value: Option<ExprId>, cleanup: Vec<SymbolId>, source: InputSpan) -> Result<Control, RuntimeError> {
        let result = self.return_value(value)?;
        for symbol in cleanup {
            self.destroy(symbol, source)?;
        }
        return Ok(result);
    }

    fn execute_generated(&mut self, kind: Operation, source: InputSpan) -> Result<Control, RuntimeError> {
        match kind {
            Operation::Declare(symbol) => {
                self.declare(symbol, source)?;
                Ok(Control::Continue)
            }
            Operation::Initialize { symbol, value } => {
                let computed = self.evaluate(value)?;
                self.write_symbol(symbol, computed, source)?;
                Ok(Control::Continue)
            }
            Operation::Store { place, value } => {
                let computed = self.evaluate(value)?;
                self.write(place, computed, source)?;
                Ok(Control::Continue)
            }
            Operation::Call(value) => {
                self.evaluate(value)?;
                Ok(Control::Continue)
            }
            Operation::Block { scope: _scope, body } => {
                for child in body {
                    let flow = self.execute(child)?;
                    match flow {
                        Control::Return(value) => {
                            return self.control_return(value);
                        }
                        Control::Continue => {
                            self.no_op()?;
                        }
                    }
                }
                Ok(Control::Continue)
            }
            Operation::If { condition, then_branch, else_branch } => {
                let test = self.condition_truthy(condition, source)?;
                if test {
                    return self.execute(then_branch);
                }
                self.execute_optional(else_branch)
            }
            Operation::While { condition, body } => {
                while self.condition_truthy(condition, source)? {
                    let flow = self.execute(body)?;
                    match flow {
                        Control::Return(value) => {
                            return self.control_return(value);
                        }
                        Control::Continue => {
                            self.no_op()?;
                        }
                    }
                }
                Ok(Control::Continue)
            }
            Operation::For { scope: _scope, initialization, condition, body, update } => {
                let initial = self.execute(initialization)?;
                match initial {
                    Control::Return(value) => {
                        return self.control_return(value);
                    }
                    Control::Continue => {
                        self.no_op()?;
                    }
                }
                while self.condition_truthy(condition, source)? {
                    let flow = self.execute(body)?;
                    match flow {
                        Control::Return(value) => {
                            return self.control_return(value);
                        }
                        Control::Continue => {
                            self.no_op()?;
                        }
                    }
                    let step = self.execute(update)?;
                    match step {
                        Control::Return(value) => {
                            return self.control_return(value);
                        }
                        Control::Continue => {
                            self.no_op()?;
                        }
                    }
                }
                Ok(Control::Continue)
            }
            Operation::Error => {
                self.invalid_operation(source)
            }
            Operation::CompoundStore { place, value } => {
                self.execute_compound_store(place, value, source)?;
                Ok(Control::Continue)
            }
            Operation::Return { value, cleanup } => {
                self.return_with_cleanup(value, cleanup, source)
            }
            Operation::Construct(symbol, constructor, arguments) => {
                self.construct(symbol, constructor, arguments, source)
            }
            Operation::Destroy(symbol) => {
                self.destroy(symbol, source)?;
                Ok(Control::Continue)
            }
        }
    }

    fn evaluate_generated(&mut self, kind: ExpressionKind, checks: Vec<RuntimeCheck>, expression: ExprId, source: InputSpan) -> Result<Value, RuntimeError> {
        match kind {
            ExpressionKind::Error => {
                self.invalid_value(source)
            }
            ExpressionKind::Constant(value) => {
                self.value_from_constant(value, expression)
            }
            ExpressionKind::Load(place) => {
                self.load(place, source)
            }
            ExpressionKind::Convert { value, target } => {
                let original = self.evaluate(value)?;
                self.convert(original, target, source)
            }
            ExpressionKind::Negate(value) => {
                let original = self.evaluate(value)?;
                self.negate(original, source)
            }
            ExpressionKind::Binary { operator, left, right } => {
                let lhs = self.evaluate(left)?;
                let rhs = self.evaluate(right)?;
                self.binary_checked(operator, right, lhs, rhs, checks, source)
            }
            ExpressionKind::Call { function, arguments } => {
                self.evaluate_call(function, arguments, source)
            }
            ExpressionKind::MethodCall { function, receiver, arguments } => {
                self.evaluate_method_call(function, receiver, arguments, source)
            }
        }
    }
}
